using System;
using SampleDotNet6App.Models;
using Xunit;

namespace SampleDotNet6App.Models.Tests;

public class UserTests
{
    [Fact]
    public void Constructor_CreatesInstance()
    {
        // Act
        var user = new User();

        // Assert
        Assert.NotNull(user);
    }

    [Fact]
    public void Id_CanSetAndGet()
    {
        // Arrange
        var user = new User();

        // Act
        user.Id = 123;

        // Assert
        Assert.Equal(123, user.Id);
    }

    [Fact]
    public void Username_DefaultValue_IsEmptyString()
    {
        // Arrange & Act
        var user = new User();

        // Assert
        Assert.Equal(string.Empty, user.Username);
    }

    [Fact]
    public void Username_CanSetAndGet()
    {
        // Arrange
        var user = new User();

        // Act
        user.Username = "testuser";

        // Assert
        Assert.Equal("testuser", user.Username);
    }

    [Fact]
    public void Email_DefaultValue_IsEmptyString()
    {
        // Arrange & Act
        var user = new User();

        // Assert
        Assert.Equal(string.Empty, user.Email);
    }

    [Fact]
    public void Email_CanSetAndGet()
    {
        // Arrange
        var user = new User();

        // Act
        user.Email = "test@example.com";

        // Assert
        Assert.Equal("test@example.com", user.Email);
    }

    [Fact]
    public void PasswordHash_DefaultValue_IsEmptyString()
    {
        // Arrange & Act
        var user = new User();

        // Assert
        Assert.Equal(string.Empty, user.PasswordHash);
    }

    [Fact]
    public void PasswordHash_CanSetAndGet()
    {
        // Arrange
        var user = new User();

        // Act
        user.PasswordHash = "hashedpassword123";

        // Assert
        Assert.Equal("hashedpassword123", user.PasswordHash);
    }

    [Fact]
    public void User_CanSetAllProperties()
    {
        // Arrange
        var user = new User();

        // Act
        user.Id = 1;
        user.Username = "user1";
        user.Email = "user1@example.com";
        user.PasswordHash = "hash1";

        // Assert
        Assert.Equal(1, user.Id);
        Assert.Equal("user1", user.Username);
        Assert.Equal("user1@example.com", user.Email);
        Assert.Equal("hash1", user.PasswordHash);
    }

    [Fact]
    public void User_ObjectInitializer_SetsProperties()
    {
        // Act
        var user = new User
        {
            Id = 2,
            Username = "user2",
            Email = "user2@example.com",
            PasswordHash = "hash2"
        };

        // Assert
        Assert.Equal(2, user.Id);
        Assert.Equal("user2", user.Username);
        Assert.Equal("user2@example.com", user.Email);
        Assert.Equal("hash2", user.PasswordHash);
    }

    [Fact]
    public void Username_CanSetToEmptyString()
    {
        // Arrange
        var user = new User { Username = "user" };

        // Act
        user.Username = string.Empty;

        // Assert
        Assert.Equal(string.Empty, user.Username);
    }

    [Fact]
    public void Email_CanSetToEmptyString()
    {
        // Arrange
        var user = new User { Email = "test@test.com" };

        // Act
        user.Email = string.Empty;

        // Assert
        Assert.Equal(string.Empty, user.Email);
    }

    [Fact]
    public void PasswordHash_CanSetToEmptyString()
    {
        // Arrange
        var user = new User { PasswordHash = "hash" };

        // Act
        user.PasswordHash = string.Empty;

        // Assert
        Assert.Equal(string.Empty, user.PasswordHash);
    }

    [Fact]
    public void Email_CanContainSpecialCharacters()
    {
        // Arrange
        var user = new User();

        // Act
        user.Email = "test+tag@example-domain.co.uk";

        // Assert
        Assert.Equal("test+tag@example-domain.co.uk", user.Email);
    }

    [Fact]
    public void Username_CanContainNumbers()
    {
        // Arrange
        var user = new User();

        // Act
        user.Username = "user123";

        // Assert
        Assert.Equal("user123", user.Username);
    }

    [Fact]
    public void Id_CanBeNegative()
    {
        // Arrange
        var user = new User();

        // Act
        user.Id = -1;

        // Assert
        Assert.Equal(-1, user.Id);
    }
}

