using System;
using SampleDotNet6App.Models;
using Xunit;

namespace SampleDotNet6App.Models.Tests;

public class ProductTests
{
    [Fact]
    public void Constructor_CreatesInstance()
    {
        // Act
        var product = new Product();

        // Assert
        Assert.NotNull(product);
    }

    [Fact]
    public void Id_CanSetAndGet()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Id = 123;

        // Assert
        Assert.Equal(123, product.Id);
    }

    [Fact]
    public void Name_DefaultValue_IsEmptyString()
    {
        // Arrange & Act
        var product = new Product();

        // Assert
        Assert.Equal(string.Empty, product.Name);
    }

    [Fact]
    public void Name_CanSetAndGet()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Name = "Test Product";

        // Assert
        Assert.Equal("Test Product", product.Name);
    }

    [Fact]
    public void Description_DefaultValue_IsNull()
    {
        // Arrange & Act
        var product = new Product();

        // Assert
        Assert.Null(product.Description);
    }

    [Fact]
    public void Description_CanSetAndGet()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Description = "Test Description";

        // Assert
        Assert.Equal("Test Description", product.Description);
    }

    [Fact]
    public void Description_CanSetToNull()
    {
        // Arrange
        var product = new Product { Description = "Some text" };

        // Act
        product.Description = null;

        // Assert
        Assert.Null(product.Description);
    }

    [Fact]
    public void Price_DefaultValue_IsZero()
    {
        // Arrange & Act
        var product = new Product();

        // Assert
        Assert.Equal(0m, product.Price);
    }

    [Fact]
    public void Price_CanSetAndGet()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Price = 99.99m;

        // Assert
        Assert.Equal(99.99m, product.Price);
    }

    [Fact]
    public void Price_CanSetNegativeValue()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Price = -10.00m;

        // Assert
        Assert.Equal(-10.00m, product.Price);
    }

    [Fact]
    public void Product_CanSetAllProperties()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Id = 1;
        product.Name = "Product 1";
        product.Description = "Description 1";
        product.Price = 19.99m;

        // Assert
        Assert.Equal(1, product.Id);
        Assert.Equal("Product 1", product.Name);
        Assert.Equal("Description 1", product.Description);
        Assert.Equal(19.99m, product.Price);
    }

    [Fact]
    public void Product_ObjectInitializer_SetsProperties()
    {
        // Act
        var product = new Product
        {
            Id = 2,
            Name = "Product 2",
            Description = "Description 2",
            Price = 29.99m
        };

        // Assert
        Assert.Equal(2, product.Id);
        Assert.Equal("Product 2", product.Name);
        Assert.Equal("Description 2", product.Description);
        Assert.Equal(29.99m, product.Price);
    }

    [Fact]
    public void Name_CanSetToEmptyString()
    {
        // Arrange
        var product = new Product { Name = "Product" };

        // Act
        product.Name = string.Empty;

        // Assert
        Assert.Equal(string.Empty, product.Name);
    }

    [Fact]
    public void Price_AccuracyTest_WithLargeDecimal()
    {
        // Arrange
        var product = new Product();

        // Act
        product.Price = 999999999.99m;

        // Assert
        Assert.Equal(999999999.99m, product.Price);
    }
}

