using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using SampleDotNet6App.Data;
using SampleDotNet6App.Models;
using SampleDotNet6App.Services;
using Xunit;

namespace SampleDotNet6App.Services.Tests;

public class ProductServiceTests
{
    [Fact]
    public void Constructor_WithValidContext_CreatesService()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Constructor")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        var service = new ProductService(context);

        // Assert
        Assert.NotNull(service);
    }

    [Fact]
    public async Task GetAllProductsAsync_WhenNoProducts_ReturnsEmptyList()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_GetAllEmpty")
            .Options;
        var context = new ApplicationDbContext(options);
        var service = new ProductService(context);

        // Act
        var result = await service.GetAllProductsAsync();

        // Assert
        Assert.NotNull(result);
        Assert.Empty(result);
    }

    [Fact]
    public async Task GetAllProductsAsync_WhenProductsExist_ReturnsAllProducts()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_GetAll")
            .Options;
        var context = new ApplicationDbContext(options);

        context.Products.AddRange(
            new Product { Id = 1, Name = "Product1", Price = 10m },
            new Product { Id = 2, Name = "Product2", Price = 20m },
            new Product { Id = 3, Name = "Product3", Price = 30m }
        );
        await context.SaveChangesAsync();

        var service = new ProductService(context);

        // Act
        var result = await service.GetAllProductsAsync();

        // Assert
        Assert.Equal(3, result.Count());
    }

    [Fact]
    public async Task GetProductByIdAsync_WhenProductExists_ReturnsProduct()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_GetById")
            .Options;
        var context = new ApplicationDbContext(options);

        context.Products.Add(new Product { Id = 1, Name = "Product1", Price = 10m });
        await context.SaveChangesAsync();

        var service = new ProductService(context);

        // Act
        var result = await service.GetProductByIdAsync(1);

        // Assert
        Assert.NotNull(result);
        Assert.Equal(1, result.Id);
        Assert.Equal("Product1", result.Name);
    }

    [Fact]
    public async Task GetProductByIdAsync_WhenProductDoesNotExist_ReturnsNull()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_GetByIdNull")
            .Options;
        var context = new ApplicationDbContext(options);
        var service = new ProductService(context);

        // Act
        var result = await service.GetProductByIdAsync(999);

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public async Task CreateProductAsync_WithValidProduct_AddsProductToDatabase()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Create")
            .Options;
        var context = new ApplicationDbContext(options);
        var service = new ProductService(context);

        var newProduct = new Product { Id = 1, Name = "NewProduct", Price = 50m };

        // Act
        var result = await service.CreateProductAsync(newProduct);

        // Assert
        Assert.NotNull(result);
        Assert.Equal("NewProduct", result.Name);
        Assert.Equal(1, context.Products.Count());
    }

    [Fact]
    public async Task CreateProductAsync_ReturnsCreatedProduct()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_CreateReturn")
            .Options;
        var context = new ApplicationDbContext(options);
        var service = new ProductService(context);

        var newProduct = new Product { Id = 1, Name = "NewProduct", Price = 50m };

        // Act
        var result = await service.CreateProductAsync(newProduct);

        // Assert
        Assert.Same(newProduct, result);
    }

    [Fact]
    public async Task UpdateProductAsync_WithExistingProduct_UpdatesProduct()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Update")
            .Options;
        var context = new ApplicationDbContext(options);

        var product = new Product { Id = 1, Name = "Original", Price = 10m };
        context.Products.Add(product);
        await context.SaveChangesAsync();
        context.Entry(product).State = EntityState.Detached;

        var service = new ProductService(context);
        var updatedProduct = new Product { Id = 1, Name = "Updated", Price = 20m };

        // Act
        await service.UpdateProductAsync(updatedProduct);

        // Assert
        var result = await context.Products.FindAsync(1);
        Assert.Equal("Updated", result!.Name);
        Assert.Equal(20m, result.Price);
    }

    [Fact]
    public async Task DeleteProductAsync_WhenProductExists_RemovesProduct()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_Delete")
            .Options;
        var context = new ApplicationDbContext(options);

        context.Products.Add(new Product { Id = 1, Name = "ToDelete", Price = 10m });
        await context.SaveChangesAsync();

        var service = new ProductService(context);

        // Act
        await service.DeleteProductAsync(1);

        // Assert
        Assert.Equal(0, context.Products.Count());
    }

    [Fact]
    public async Task DeleteProductAsync_WhenProductDoesNotExist_DoesNothing()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_DeleteNonExistent")
            .Options;
        var context = new ApplicationDbContext(options);
        var service = new ProductService(context);

        // Act
        await service.DeleteProductAsync(999);

        // Assert
        Assert.Equal(0, context.Products.Count());
    }

    [Fact]
    public async Task CreateProductAsync_WithDescription_SavesDescription()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_CreateWithDesc")
            .Options;
        var context = new ApplicationDbContext(options);
        var service = new ProductService(context);

        var newProduct = new Product { Id = 1, Name = "Product", Description = "Test Description", Price = 50m };

        // Act
        await service.CreateProductAsync(newProduct);

        // Assert
        var saved = await context.Products.FindAsync(1);
        Assert.Equal("Test Description", saved!.Description);
    }

    [Fact]
    public async Task GetAllProductsAsync_ReturnsProductsInOrder()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_GetAllOrder")
            .Options;
        var context = new ApplicationDbContext(options);

        context.Products.AddRange(
            new Product { Id = 3, Name = "Product3", Price = 30m },
            new Product { Id = 1, Name = "Product1", Price = 10m },
            new Product { Id = 2, Name = "Product2", Price = 20m }
        );
        await context.SaveChangesAsync();

        var service = new ProductService(context);

        // Act
        var result = await service.GetAllProductsAsync();

        // Assert
        var list = result.ToList();
        Assert.Equal(3, list.Count);
    }
}

