using System.Linq;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using SampleDotNet6App.Data;
using SampleDotNet6App.Models;
using Xunit;

namespace SampleDotNet6App.Data.Tests;

public class DataSeederTests
{
    [Fact]
    public async Task SeedAsync_WhenDatabaseEmpty_SeedsProducts()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_SeedProducts")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        var products = context.Products.ToList();
        Assert.NotEmpty(products);
        Assert.Equal(3, products.Count);
    }

    [Fact]
    public async Task SeedAsync_WhenDatabaseEmpty_SeedsUsers()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_SeedUsers")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        var users = context.Users.ToList();
        Assert.NotEmpty(users);
        Assert.Equal(2, users.Count);
    }

    [Fact]
    public async Task SeedAsync_WhenProductsExist_DoesNotDuplicateProducts()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_NoDuplicateProducts")
            .Options;
        var context = new ApplicationDbContext(options);

        context.Products.Add(new Product { Id = 99, Name = "Existing", Price = 1.00m });
        await context.SaveChangesAsync();

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        var products = context.Products.ToList();
        Assert.Single(products);
        Assert.Equal("Existing", products[0].Name);
    }

    [Fact]
    public async Task SeedAsync_WhenUsersExist_DoesNotDuplicateUsers()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_NoDuplicateUsers")
            .Options;
        var context = new ApplicationDbContext(options);

        context.Users.Add(new User { Id = 99, Username = "existing", Email = "existing@test.com", PasswordHash = "hash" });
        await context.SaveChangesAsync();

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        var users = context.Users.ToList();
        Assert.Single(users);
        Assert.Equal("existing", users[0].Username);
    }

    [Fact]
    public async Task SeedAsync_SeedsCorrectProductData()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_CorrectProductData")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        var product1 = context.Products.FirstOrDefault(p => p.Id == 1);
        Assert.NotNull(product1);
        Assert.Equal("Product 1", product1.Name);
        Assert.Equal(19.99m, product1.Price);
        Assert.Equal("Description 1", product1.Description);
    }

    [Fact]
    public async Task SeedAsync_SeedsCorrectUserData()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_CorrectUserData")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        var user1 = context.Users.FirstOrDefault(u => u.Id == 1);
        Assert.NotNull(user1);
        Assert.Equal("user1", user1.Username);
        Assert.Equal("user1@example.com", user1.Email);
        Assert.Equal("hash1", user1.PasswordHash);
    }

    [Fact]
    public async Task SeedAsync_SavesChangesToDatabase()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_SavesChanges")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        await DataSeeder.SeedAsync(context);

        // Assert
        using (var newContext = new ApplicationDbContext(options))
        {
            Assert.Equal(3, newContext.Products.Count());
            Assert.Equal(2, newContext.Users.Count());
        }
    }

    [Fact]
    public async Task SeedAsync_CallMultipleTimes_OnlySeedsOnce()
    {
        // Arrange
        var options = new DbContextOptionsBuilder<ApplicationDbContext>()
            .UseInMemoryDatabase(databaseName: "TestDb_SeedsOnce")
            .Options;
        var context = new ApplicationDbContext(options);

        // Act
        await DataSeeder.SeedAsync(context);
        await DataSeeder.SeedAsync(context);
        await DataSeeder.SeedAsync(context);

        // Assert
        Assert.Equal(3, context.Products.Count());
        Assert.Equal(2, context.Users.Count());
    }
}

